NAME = 'GerZurcher: Deutsche Zürcher Bibel von 1931.'
BOOK = 'Lamentations'

CHAPTERS = {
    1: {
        1: 'ACH, wie sitzt so einsam die Stadt, einst reich an Volk! / wie ist sie zur Witwe geworden, die gross war unter den Völkern! / Die da Fürstin war unter den Städten, ist dienstbar geworden. / (a) Jer 51:5',
        2: 'Sie weint und weint durch die Nacht, Tränen auf der Wange; / keiner ist da, der sie tröste, von all ihren Liebhabern, / all ihre Freunde sind untreu, sind ihr zu Feinden geworden. /',
        3: 'Fort aus der Heimat ist Juda vor Elend und harter Knechtschaft; / nun weilt es unter den Heiden, findet keine Ruhstatt. / Alle seine Verfolger holen es ein inmitten der Bedrängnis. /',
        4: 'Die Wege nach Zion trauern, niemand pilgert zum Feste. / All ihre Tore sind verödet, ihre Priester seufzen, / ihre Jungfrauen sind verhärmt, sie selbst hat bitteres Weh. /',
        5: 'Ihre Bedränger sind obenauf, ihren Feinden geht es wohl; / denn der Herr hat ihr Trübsal gesandt um all ihrer Sünden willen. / Gefangen sind ihre Kindlein, von dannen gezogen vor dem Bedränger her. /',
        6: 'Entschwunden ist der Tochter Zion all ihre Herrlichkeit; / ihre Fürsten wurden gleich Hirschen, die keine Weide finden; / sie zogen kraftlos dahin vor dem Verfolger. /',
        7: 'Jerusalem gedenkt der Tage ihres Elends und ihrer Irrsal, / all ihrer Kostbarkeiten, die sie einstmals besass, / da ihr Volk in Feindeshand fiel, keiner ihr half. / Ihre Feinde schauten sie, lachten ob ihrer Vernichtung. /',
        8: 'Schwer hat Jerusalem gesündigt, drum ist sie zum Abscheu geworden; / die sie in Ehren hielten, verachten sie, weil sie ihre Blösse gesehen. / Auch sie selber seufzt und wendet sich ab. /',
        9: 'Besudelt ist ihre Schleppe, sie hat nicht das Ende bedacht. / So ist sie gar tief gefallen; niemand ist, der sie tröste. / "Ach, Herr, siehe an mein Elend, denn gross tut der Feind!" /',
        10: 'Der Feind hat seine Hand ausgestreckt nach allem, was sie Köstliches hatte; / denn sie hat sehen müssen, wie Heiden in ihr Heiligtum drangen, / denen du doch verboten, in deine Gemeinde zu kommen. / (a) Jer 52:17-23',
        11: 'All ihre Bewohner seufzen, suchen nach Brot; / was einer Köstliches hat, / das gibt er um Speise, das Leben zu fristen. / "Sieh doch, o Herr, und schaue, wie verachtet ich bin!" / (a) Kla 4:9; Jer 52:6',
        12: '"Kommt, ihr alle, die ihr vorübergeht, schauet und seht, / ob ein Schmerz sei wie der Schmerz, der mir angetan worden, / mit dem der Herr mich geschlagen am Tage seines glühenden Zorns. /',
        13: 'Aus der Höhe hat er Feuer / in meine Gebeine gesandt, mich gezüchtigt, / meinen Füssen hat er ein Netz gespannt, mich zurückgerissen; / er hat mich verstört, mich krank gemacht allezeit. /',
        14: 'Er hat gewacht über meine Sünden, sie schlangen sich um meine Hände; / sie lasten als Joch auf meinem Nacken, haben meine Kraft gebrochen. / Der Herr hat mich in die Hand derer gegeben, denen ich nicht widerstehen konnte. /',
        15: 'Alle Helden in meinem Bereich hat der Herr verworfen, / hat ein Fest wider mich ausgerufen, meine Jungmannschaft zu zerschmettern. / Die Kelter hat der Herr getreten der Jungfrau, der Tochter Juda. / (a) Jes 63:3',
        16: 'Darob weine ich, mein Auge zerfliesst in Tränen; / denn fern von mir ist der Tröster, der mich erquicken könnte. / Meine Kinder sind verstört; denn der Feind ist übermächtig." /',
        17: 'Zion streckt ihre Hände aus, doch niemand ist, der sie tröste. / Der Herr hat wider Jakob entboten die Feinde ringsumher; / Jerusalem ist unter ihnen zum Abscheu geworden. /',
        18: '"Der Herr allein ist im Recht; denn seinem Worte habe ich getrotzt. / Hört doch, ihr Völker alle, schaut an meinen Schmerz! / Meine Jungfrauen und Jünglinge sind gefangen von dannen gezogen. /',
        19: 'Ich rief meinen Liebhabern, doch sie betrogen mich; / meine Priester und Ältesten sind in der Stadt verschmachtet: / sie suchten sich Speise und fanden keine. / (a) Jer 30:14',
        20: 'O Herr, sieh doch, mir ist so bange, es glüht mir in der Brust; / mein Herz kehrt sich um in mir, weil ich so trotzig war. / Draussen hat mir das Schwert die Kinder geraubt und drinnen die Seuche. /',
        21: 'Höre doch, wie ich seufze, ohne dass einer mich tröstet! / All meine Feinde kennen mein Unglück, sie freuen sich, dass du es getan, / dass du den Tag herbeigeführt, den du ausgerufen um all meiner Sünden willen. /',
        22: 'All ihre Bosheit komme vor dein Angesicht! Sie mögen mir gleich werden! / Wie du mir getan hast, so tue auch ihnen! / Denn meiner Seufzer sind viel, und mein Herz ist krank." (a) Jer 8:18',
    },
    2: {
        1: 'ACH, wie umwölkt in seinem Zorn der Herr die Tochter Zion! / Vom Himmel hat er zur Erde geschleudert die Herrlichkeit Israels, / hat des Schemels seiner Füsse nicht gedacht am Tag seines Zorns. /',
        2: 'Erbarmungslos hat der Herr vernichtet alle Auen Jakobs, / hat niedergerissen in seinem Grimm die Festen der Tochter Juda, / hat zu Boden geworfen, entweiht das Königreich und seine Fürsten. /',
        3: 'Abgehauen hat er in glühendem Zorn jegliches Horn Israels, / hat seine Rechte zurückgezogen beim Nahen des Feindes, / hat Jakob versengt wie eine feurige Lohe, die um sich frisst. / (1) im AT häufiges Sinnbild der Kraft, vgl. 1Sa 2:1.',
        4: 'Er hat seinen Bogen gespannt wie ein Feind, dastehend wie ein Bedränger, / und alle Augenweide gemordet im Zelt der Tochter Zion; / seinen Grimm hat er ausgeschüttet wie Feuer. /',
        5: 'Der Herr ist geworden wie ein Feind, hat Israel vernichtet, / vernichtet alle seine Paläste, zerstört seine Festen / und Jammer auf Jammer gehäuft über die Tochter Juda. /',
        6: 'Er hat seine Hütte verwüstet, hat seinen Festort verheert; / in Vergessenheit gebracht hat der Herr Festtag und Sabbat in Zion, / hat König und Priester verworfen in seinem grimmigen Zorn. /',
        7: 'Seinen Altar hat der Herr verstossen, verworfen sein Heiligtum, / die Mauern von Zions Palästen in die Hand der Feinde gegeben; / im Hause des Herrn erscholl ihr Geschrei wie am Festtag. /',
        8: 'Der Herr hat beschlossen, zu verderben die Mauern der Tochter Zion; / er hat die Meßschnur ausgespannt, seiner Hand nicht gewehrt zu zerstören. / Trauern müssen Bollwerk und Mauer, allzumal härmen sie sich. / (a) 2Kön 21:13',
        9: 'Ihre Tore sind in die Erde versunken, zerschlagen sind ihre Riegel. / Ihr König und ihre Fürsten sind unter den Heiden, der Weisung entbehrend, / auch ihre Propheten empfangen keine Gesichte vom Herrn. /',
        10: 'Stumm sitzen am Boden die Ältesten der Tochter Zion, / Staub auf das Haupt gestreut, das Trauertuch umgegürtet; / die Jungfrauen Jerusalems senken das Haupt zur Erde. /',
        11: 'Meine Augen schwanden dahin in Tränen, es glühte mir in der Brust; / mir brach das Herz ob dem Untergang der Tochter meines Volkes, / da Kindlein und Säuglinge verschmachteten auf den Plätzen der Stadt. / (1) w: "es glühten meine Eingeweide, zur Erde ward ausgeschüttet meine Leber".',
        12: 'Sie sprachen zu ihren Müttern: "Wo ist Brot?" / da sie wie Todwunde verschmachteten auf den Plätzen der Stadt, / da sie ihre Seelen aushauchten an der Brust ihrer Mütter. /',
        13: 'Was soll ich neben dich stellen, womit dich vergleichen, Tochter Jerusalem? / was dir gleichsetzen, dich zu trösten, Jungfrau, Tochter Zion? / Denn gross wie das Meer ist dein Verderben; wer könnte dich heilen? /',
        14: 'Deine Propheten haben dir erschaut Trug und Tünche, / haben nicht aufgedeckt deine Schuld, die Verbannung von dir zu wenden, / sie haben dir Aussprüche erschaut der Lüge und der Verführung. / (a) Jer 5:31; 14:14; 23:16',
        15: 'Alle, die des Weges vorübergingen, klatschten über dich in die Hände, / höhnten und schüttelten den Kopf über die Tochter Jerusalem: / "Ist das die Stadt, die man die schönste nannte, die Wonne der ganzen Erde?" / (a) Ps 48:3; 50:2; Hes 16:14',
        16: 'Alle deine Feinde rissen das Maul über dich auf, / höhnten und knirschten mit den Zähnen, sprachen: "Wir haben sie vernichtet! / Ja, das ist der Tag, auf den wir gehofft; wir haben ihn erlebt, geschaut." / (a) Kla 3:46',
        17: 'Der Herr hat vollbracht, was er beschlossen, hat ausgeführt, was er gedroht, / was er seit der Vorzeit befohlen, hat niedergerissen ohne Erbarmen, / den Feind über dich frohlocken lassen, das Horn deiner Dränger erhoben. / (1) s. Anm. zu V. 3.',
        18: 'Schreie laut zum Herren, Jungfrau, Tochter Zion! / Lass strömen die Tränen wie einen Bach bei Tag und bei Nacht! / Gönne dir keine Ruhe, dein Auge raste nicht! /',
        19: 'Stehe auf, klage in der Nacht, zu Beginn jeder Nachtwache! / Schütte dein Herz aus wie Wasser vor dem Angesichte des Herrn! / Erhebe zu ihm deine Hände für das Leben deiner Kindlein, / die dahinschmachten vor Hunger an allen Enden der Strassen! / (a) Ps 62:9',
        20: 'Sieh doch, o Herr, und schaue: Wem hast du solches getan? / Sollen Mütter ihre Leibesfrucht essen, die Kinder, die sie gehätschelt? / Sollen im Heiligtum des Herrn gemordet werden Priester und Prophet? / (a) Jer 19:9',
        21: 'Hingestreckt auf den Strassen liegen Knabe und Greis, / meine Jungfrauen und Jünglinge sind durch das Schwert gefallen; / du hast sie gemordet am Tag deines Zorns, erbarmungslos sie geschlachtet. /',
        22: 'Du beriefst sie wie am Festtag aus meinen Weilern ringsum; / doch am Tage des Zornes des Herrn ist keiner entronnen, entkommen. / Die ich gehätschelt und grossgezogen, mein Feind hat sie vertilgt.',
    },
    3: {
        1: 'ICH bin der Mann, der Elend erfahren durch die Rute seines Grimms. /',
        2: 'Er hat mich getrieben, mich geführt in lichtloses Dunkel. /',
        3: 'Nur gegen mich kehrt er immer wieder, den ganzen Tag, seine Hand. /',
        4: 'Hinschwinden liess er mir Fleisch und Haut, zerbrach mein Gebein. /',
        5: 'Aufgetürmt hat er rings um mich Bitterkeit und Mühsal, /',
        6: 'hat mich in Finsternis gelegt gleich ewig Toten. /',
        7: 'Er hat mir jeden Ausgang versperrt, mich in schwere Fesseln geschlagen. / (a) Hio 3:23; 19:8',
        8: 'Ob ich gleich schreie und flehe - er verlegt meinem Gebete den Weg. /',
        9: 'Er hat meine Wege mit Quadern versperrt, hat krumm gemacht meine Pfade. /',
        10: 'Er lauert auf mich wie ein Bär, wie ein Löwe im Versteck. / (a) Hio 10:16',
        11: 'Er hat mich Irrwege geführt und mich zerfleischt, mich verstört. /',
        12: 'Er hat seinen Bogen gespannt und mich dem Pfeil zum Ziele gesetzt, / (a) Hio 16:12',
        13: 'hat die Söhne seines Köchers mir in die Nieren geschossen. /',
        14: 'Ich bin meinem ganzen Volk / zum Gelächter geworden, zum Spottlied den ganzen Tag. / (a) Hio 30:9',
        15: 'Er hat mich gesättigt mit Bitterkeit, mich mit Wermut getränkt. /',
        16: 'Er liess meine Zähne an Kies sich zerreiben, trat mich in die Asche nieder, /',
        17: 'verstiess meine Seele aus dem Frieden. Des Glücks vergass ich /',
        18: 'und dachte: Dahin ist mein Glanz, dahin meine Hoffnung auf den Herrn. /',
        19: 'Meines Elends und meiner Irrsal zu gedenken, ist Wermut und Gift. /',
        20: 'Ohne Unterlass denkt meine Seele daran und ist gebeugt in mir. /',
        21: 'Das will ich zu Herzen nehmen, darum will ich hoffen: /',
        22: 'Die Guttaten des Herrn sind noch nicht aus, ja, sie sind noch nicht zu Ende. /',
        23: 'Jeden Morgen neu ist sein Erbarmen, und gross ist seine Treue. /',
        24: 'Der Herr ist mein Teil, spricht meine Seele, darum will ich auf ihn hoffen. / (a) Ps 16:5; 73:26',
        25: 'Der Herr ist gütig gegen den, der auf ihn hofft, gegen die Seele, die ihn sucht. /',
        26: 'Es ist gut, in Stille zu harren auf die Hilfe des Herrn. / (a) Ps 62:2',
        27: 'Es ist dem Manne gut, ein Joch zu tragen in seiner Jugend. /',
        28: 'Er sitze einsam und schweige, wenn er es ihm auflegt. /',
        29: 'Er beuge seinen Mund in den Staub, vielleicht ist noch Hoffnung. /',
        30: 'Er biete dem, der ihn schlägt, den Backen, lasse sich sättigen mit Schmach. / (a) Jes 50:6; Mt 5:39',
        31: 'Denn der Herr wird nicht auf ewig verstossen: /',
        32: 'wenn er betrübt hat, erbarmt er sich wieder nach der Fülle seiner Gnade; /',
        33: 'denn nicht aus Lust plagt und betrübt er die Menschenkinder. /',
        34: 'Dass man mit Füssen tritt alle Gefangenen der Erde, /',
        35: 'dass man das Recht des Mannes beugt vor dem Höchsten, /',
        36: 'dass man den Menschen bedrückt / in seinem Rechtsstreit, sollte der Herr das nicht sehen? /',
        37: 'Wer kann so befehlen, dass etwas geschieht, ohne dass der Herr es geboten? /',
        38: 'Kommt nicht vom Munde des Höchsten so Glück wie Unglück? / (a) Jes 45:7; Am 3:6',
        39: 'Worüber soll klagen der Mensch, der da lebt? Ein jeder über seine Sünde! /',
        40: 'Lasset uns prüfen und erforschen unsre Wege und umkehren zum Herrn! /',
        41: 'Lasset uns unsre Herzen als Opfer darbringen vor Gott im Himmel! /',
        42: 'Wir sind abtrünnig und widerspenstig gewesen; darum hast du nicht vergeben, /',
        43: 'hast dich in Zorn gehüllt und uns verfolgt, hast getötet und nicht geschont, /',
        44: 'hast dich in Gewölk gehüllt, dass das Gebet nicht hindurchdrang. /',
        45: 'Du hast uns zum Auswurf gemacht, zum Abscheu unter den Völkern. /',
        46: 'All unsre Feinde haben über uns das Maul aufgerissen; / (a) Kla 2:16',
        47: 'Grauen und Grube sind uns geworden, Verwüstung und Verderben. /',
        48: 'Von Wasserbächen strömt mein Auge ob dem Sturz meines Volkes. /',
        49: 'Ruhelos fliesst mein Auge und kann nicht aufhören, /',
        50: 'bis der Herr vom Himmel herabschaut und dareinsieht. /',
        51: 'Mein Auge schmerzt mich um der Töchter meiner Stadt willen. /',
        52: 'Gejagt haben mich wie einen Vogel, die mir feind sind ohne Ursache. /',
        53: 'Sie haben mein Leben in der Grube vernichtet und Steine auf mich geworfen. / (a) Jer 38:6',
        54: 'Die Wasser gingen über mein Haupt, ich dachte: Nun bin ich verloren. /',
        55: 'Ich rief deinen Namen an, o Herr, aus der Tiefe der Grube. / (a) Ps 130:1',
        56: 'Du hast meine Stimme gehört; verschliesse nicht dein Ohr meinem Flehen. /',
        57: 'Du warst nahe, als ich dich anrief; du hast gesprochen: Fürchte dich nicht! /',
        58: 'Du hast, o Herr, meine Sache geführt, hast mein Leben errettet. /',
        59: 'Du hast, o Herr, meine Unbill gesehen; hilf mir zu meinem Rechte! /',
        60: 'Du hast all ihre Rachgier gesehen, all ihre Anschläge wider mich, /',
        61: 'hast ihr Schmähen gehört, o Herr, all ihre Anschläge wider mich, /',
        62: 'das Gerede meiner Widersacher, die (Böses) wider mich sinnen allezeit. /',
        63: 'Ob sie niedersitzen oder aufstehen, / achte auf sie; ich bin ihr Spottlied. /',
        64: 'Du wirst ihnen vergelten, o Herr, nach dem Tun ihrer Hände, /',
        65: 'du wirst ihre Herzen verblenden. Dein Fluch treffe sie! /',
        66: 'Du wirst sie verfolgen mit Grimm, sie vertilgen unter deinem Himmel.',
    },
    4: {
        1: 'ACH, wie schwarz wird das Gold! wie wandelt sich das edle Metall! / Hingeschüttet werden die heiligen Steine an allen Strassenecken. /',
        2: 'Die Söhne Zions, die kostbaren, mit feinem Golde nur aufzuwiegen, / wie sind sie gleichgeachtet irdenen Geschirren, dem Machwerk von Töpfers Hand! /',
        3: 'Selbst Schakale reichen die Brust, säugen ihre Jungen; / die Tochter meines Volkes ward grausam wie die Strausse in der Wüste. /',
        4: 'Dem Säugling klebte die Zunge vor Durst am Gaumen; / die Kindlein verlangten nach Brot, niemand brach es ihnen. /',
        5: 'Die einst Leckerbissen gegessen, verschmachteten auf den Strassen; / die man auf Purpur hegte, mussten auf Düngerhaufen liegen. /',
        6: 'So war denn die Schuld meines Volkes grösser als Sodoms Sünde, / das im Nu zerstört ward ohne Zutun von Menschenhand. /',
        7: 'Seine Fürsten waren reiner als Schnee, weisser als Milch; / ihr Leib war röter als Korallen, wie Saphir ihre Gestalt. /',
        8: 'Ihr Aussehen ist schwärzer geworden als Russ, man erkennt sie nicht auf den Gassen; / ihre Haut klebt an ihrem Gebein, sie ist trocken geworden wie Holz. /',
        9: 'Glücklicher waren, die das Schwert erschlug, als die der Hunger erschlug, / die, (vom Hunger) durchbohrt, hinschmachteten, aus Mangel an Früchten des Feldes. /',
        10: 'Weichherzige Frauen haben mit eignen Händen ihre Kinder gekocht; / sie sind ihre Speise geworden beim Sturz meines Volkes. / (a) Kla 2:20; Jer 19:9',
        11: 'Voll ausgewirkt hat der Herr seinen Grimm, ausgeschüttet die Glut seines Zorns, / hat Feuer an Zion gelegt; das hat seine Grundfesten verzehrt. /',
        12: "Nicht hätten's geglaubt die Könige der Erde, nicht die Bewohner alle der Welt, / dass ein Dränger und Feind eindringen würde in Jerusalems Tore. /",
        13: 'Ob der Sünden seiner Propheten ist es geschehen, ob der Schuld seiner Priester, / die das Blut der Gerechten darin vergossen haben. /',
        14: 'Sie taumelten durch die Strassen wie Blinde, befleckt mit Blut, / sodass man ihre Kleider nicht anrühren durfte. /',
        15: '"Weicht aus! ein Unreiner!" rief man vor ihnen, "weicht aus! berührt ihn nicht! / Wenn sie umhertaumeln wollen, so sollen sie nicht ferner hier bleiben!" /',
        16: 'Der Herr selber hat sie zerstreut, er will sie nimmermehr ansehen. / Der Priester achtete er nicht, erbarmte sich nicht über die Ältesten. /',
        17: 'Stetsfort schmachteten unsre Augen nach der Hilfe - vergebens! / Auf unsrer Warte spähten wir nach einem Volk, das nicht hilft. /',
        18: 'Man lauerte auf unsre Schritte, dass wir kaum über einen freien Platz gehen konnten. / Unser Ende war nahe, / unsre Tage hatten sich erfüllt; ja, unser Ende war gekommen. /',
        19: 'Unsre Verfolger waren schneller als die Adler des Himmels; / auf den Bergen haben sie nach uns gejagt, auf uns gelauert in der Wüste. /',
        20: 'Unser Lebenshauch, der Gesalbte des Herrn, ward in ihren Gruben gefangen, / er, von dem wir sagten: "In seinem Schatten werden wir leben unter den Völkern." / (a) Jer 52:8 11',
        21: 'Freue dich nur und frohlocke, Tochter Edom, die du wohnst im Lande Uz! / Auch an dich wird der Kelch kommen; du wirst trunken werden und dich entblössen. / (a) Jer 25:15 21; 49:12',
        22: 'Deine Schuld ist getilgt, Tochter Zion; er wird dich nicht mehr in die Verbannung führen. / Deine Schuld, Tochter Edom, sucht er heim, deckt auf deine Sünden. (a) Jes 40:2',
    },
    5: {
        1: 'GEDENKE, o Herr, was uns geschehen, schau her und sieh unsre Schmach! /',
        2: 'Unser Erbe ist Fremden zugefallen, Ausländern unsre Häuser. /',
        3: 'Wir sind Waisen geworden, vaterlos, unsre Mütter zu Witwen. /',
        4: 'Das Wasser, das wir trinken, müssen wir bezahlen, nur um Geld bekommen wir Holz. /',
        5: 'Auf dem Nacken sitzen uns die Verfolger; wir sind ermattet, man gönnt uns nicht Ruhe. /',
        6: 'Den Ägyptern unterwerfen wir uns, den Assyrern, um uns satt zu essen. /',
        7: 'Unsre Väter haben gesündigt, sie sind nicht mehr; und wir, wir tragen ihre Schuld. /',
        8: 'Knechte beherrschen uns, niemand entreisst uns ihrer Hand. /',
        9: 'Mit Lebensgefahr holen wir unser Brot, in Furcht vor dem Schwert der Wüste. /',
        10: 'Unsre Haut glüht wie ein Ofen vor den Gluten des Hungers. /',
        11: 'Frauen wurden in Zion geschändet, Mädchen in den Städten Judas. /',
        12: 'Die Fürsten wurden durch ihre Hand gehängt, die Ältesten nicht geehrt. /',
        13: 'Jünglinge mussten die Handmühle tragen, und Knaben strauchelten unter der Holzlast. /',
        14: 'Die Greise beraten nicht mehr im Tor, die Jünglinge lassen ihr Saitenspiel. /',
        15: 'Die Freude unsres Herzens hat ein Ende, unser Reigen hat sich in Klage verkehrt. /',
        16: 'Die Krone unsres Hauptes ist gefallen. Wehe uns, dass wir gesündigt haben! / (a) Jer 13:18',
        17: 'Darob ist unser Herz krank geworden, darob sind unsre Augen trübe, /',
        18: 'dass der Berg Zion wüste liegt, dass Füchse darauf streifen. /',
        19: 'Du, o Herr, thronest in Ewigkeit, dein Thron steht für und für. / (a) Ps 9:8; 102:13; 103:19',
        20: 'Warum willst du unser auf immer vergessen, uns so lange verlassen? /',
        21: 'Führe uns zu dir zurück, o Herr, auf dass wir wiederkehren! / Erneuere unsre Tage wie vor alters! / (a) Jer 17:14; 31:18',
        22: 'Oder hast du uns gänzlich verworfen, zürnest uns gar so sehr?',
    },
}
